mkitem!{mktrait!{# [doc = " A generalization of `Clone` to borrowed data."] # [doc = ""] # [doc = " Some types make it possible to go from borrowed to owned, usually by"] # [doc = " implementing the `Clone` trait. But `Clone` works only for going from `&T`"] # [doc = " to `T`. The `ToOwned` trait generalizes `Clone` to construct owned data"] # [doc = " from any borrow of a given type."] # [rustc_diagnostic_item = "ToOwned"] # [stable (feature = "rust1" , since = "1.0.0")] pub trait ToOwned { # [doc = " The resulting type after obtaining ownership."] # [stable (feature = "rust1" , since = "1.0.0")] type Owned : Borrow < Self > ; # [doc = " Creates owned data from borrowed data, usually by cloning."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " Basic usage:"] # [doc = ""] # [doc = " ```"] # [doc = " let s: &str = \"a\";"] # [doc = " let ss: String = s.to_owned();"] # [doc = ""] # [doc = " let v: &[i32] = &[1, 2];"] # [doc = " let vv: Vec<i32> = v.to_owned();"] # [doc = " ```"] # [stable (feature = "rust1" , since = "1.0.0")] # [must_use = "cloning is often expensive and is not expected to have side effects"] # [rustc_diagnostic_item = "to_owned_method"] fn to_owned (& self) -> Self :: Owned ; # [doc = " Uses borrowed data to replace owned data, usually by cloning."] # [doc = ""] # [doc = " This is borrow-generalized version of [`Clone::clone_from`]."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " Basic usage:"] # [doc = ""] # [doc = " ```"] # [doc = " let mut s: String = String::new();"] # [doc = " \"hello\".clone_into(&mut s);"] # [doc = ""] # [doc = " let mut v: Vec<i32> = Vec::new();"] # [doc = " [1, 2][..].clone_into(&mut v);"] # [doc = " ```"] # [stable (feature = "toowned_clone_into" , since = "1.63.0")] fn clone_into (& self , target : & mut Self :: Owned) { * target = self . to_owned () ; } }}}
mkitem!{mkimpl!{# [stable (feature = "rust1" , since = "1.0.0")] impl < T > ToOwned for T where T : Clone , { type Owned = T ; fn to_owned (& self) -> T { self . clone () } fn clone_into (& self , target : & mut T) { target . clone_from (self) ; } }}}
mkitem!{mkenum!{# [doc = " A clone-on-write smart pointer."] # [doc = ""] # [doc = " The type `Cow` is a smart pointer providing clone-on-write functionality: it"] # [doc = " can enclose and provide immutable access to borrowed data, and clone the"] # [doc = " data lazily when mutation or ownership is required. The type is designed to"] # [doc = " work with general borrowed data via the `Borrow` trait."] # [doc = ""] # [doc = " `Cow` implements `Deref`, which means that you can call"] # [doc = " non-mutating methods directly on the data it encloses. If mutation"] # [doc = " is desired, `to_mut` will obtain a mutable reference to an owned"] # [doc = " value, cloning if necessary."] # [doc = ""] # [doc = " If you need reference-counting pointers, note that"] # [doc = " [`Rc::make_mut`][crate::rc::Rc::make_mut] and"] # [doc = " [`Arc::make_mut`][crate::sync::Arc::make_mut] can provide clone-on-write"] # [doc = " functionality as well."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use std::borrow::Cow;"] # [doc = ""] # [doc = " fn abs_all(input: &mut Cow<'_, [i32]>) {"] # [doc = "     for i in 0..input.len() {"] # [doc = "         let v = input[i];"] # [doc = "         if v < 0 {"] # [doc = "             // Clones into a vector if not already owned."] # [doc = "             input.to_mut()[i] = -v;"] # [doc = "         }"] # [doc = "     }"] # [doc = " }"] # [doc = ""] # [doc = " // No clone occurs because `input` doesn't need to be mutated."] # [doc = " let slice = [0, 1, 2];"] # [doc = " let mut input = Cow::from(&slice[..]);"] # [doc = " abs_all(&mut input);"] # [doc = ""] # [doc = " // Clone occurs because `input` needs to be mutated."] # [doc = " let slice = [-1, 0, 1];"] # [doc = " let mut input = Cow::from(&slice[..]);"] # [doc = " abs_all(&mut input);"] # [doc = ""] # [doc = " // No clone occurs because `input` is already owned."] # [doc = " let mut input = Cow::from(vec![-1, 0, 1]);"] # [doc = " abs_all(&mut input);"] # [doc = " ```"] # [doc = ""] # [doc = " Another example showing how to keep `Cow` in a struct:"] # [doc = ""] # [doc = " ```"] # [doc = " use std::borrow::Cow;"] # [doc = ""] # [doc = " struct Items<'a, X> where [X]: ToOwned<Owned = Vec<X>> {"] # [doc = "     values: Cow<'a, [X]>,"] # [doc = " }"] # [doc = ""] # [doc = " impl<'a, X: Clone + 'a> Items<'a, X> where [X]: ToOwned<Owned = Vec<X>> {"] # [doc = "     fn new(v: Cow<'a, [X]>) -> Self {"] # [doc = "         Items { values: v }"] # [doc = "     }"] # [doc = " }"] # [doc = ""] # [doc = " // Creates a container from borrowed values of a slice"] # [doc = " let readonly = [1, 2];"] # [doc = " let borrowed = Items::new((&readonly[..]).into());"] # [doc = " match borrowed {"] # [doc = "     Items { values: Cow::Borrowed(b) } => println!(\"borrowed {b:?}\"),"] # [doc = "     _ => panic!(\"expect borrowed value\"),"] # [doc = " }"] # [doc = ""] # [doc = " let mut clone_on_write = borrowed;"] # [doc = " // Mutates the data from slice into owned vec and pushes a new value on top"] # [doc = " clone_on_write.values.to_mut().push(3);"] # [doc = " println!(\"clone_on_write = {:?}\", clone_on_write.values);"] # [doc = ""] # [doc = " // The data was mutated. Let's check it out."] # [doc = " match clone_on_write {"] # [doc = "     Items { values: Cow::Owned(_) } => println!(\"clone_on_write contains owned data\"),"] # [doc = "     _ => panic!(\"expect owned data\"),"] # [doc = " }"] # [doc = " ```"] # [stable (feature = "rust1" , since = "1.0.0")] # [rustc_diagnostic_item = "Cow"] pub enum Cow < 'a , B : ? Sized + 'a > where B : ToOwned , { # [doc = " Borrowed data."] # [stable (feature = "rust1" , since = "1.0.0")] Borrowed (# [stable (feature = "rust1" , since = "1.0.0")] & 'a B) , # [doc = " Owned data."] # [stable (feature = "rust1" , since = "1.0.0")] Owned (# [stable (feature = "rust1" , since = "1.0.0")] < B as ToOwned > :: Owned) , }}}
mkitem!{mkimpl!{# [stable (feature = "rust1" , since = "1.0.0")] impl < B : ? Sized + ToOwned > Clone for Cow < '_ , B > { fn clone (& self) -> Self { match * self { Borrowed (b) => Borrowed (b) , Owned (ref o) => { let b : & B = o . borrow () ; Owned (b . to_owned ()) } } } fn clone_from (& mut self , source : & Self) { match (self , source) { (& mut Owned (ref mut dest) , & Owned (ref o)) => o . borrow () . clone_into (dest) , (t , s) => * t = s . clone () , } } }}}
mkitem!{mkimpl!{impl < B : ? Sized + ToOwned > Cow < '_ , B > { # [doc = " Returns true if the data is borrowed, i.e. if `to_mut` would require additional work."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " #![feature(cow_is_borrowed)]"] # [doc = " use std::borrow::Cow;"] # [doc = ""] # [doc = " let cow = Cow::Borrowed(\"moo\");"] # [doc = " assert!(cow.is_borrowed());"] # [doc = ""] # [doc = " let bull: Cow<'_, str> = Cow::Owned(\"...moo?\".to_string());"] # [doc = " assert!(!bull.is_borrowed());"] # [doc = " ```"] # [unstable (feature = "cow_is_borrowed" , issue = "65143")] pub const fn is_borrowed (& self) -> bool { match * self { Borrowed (_) => true , Owned (_) => false , } } # [doc = " Returns true if the data is owned, i.e. if `to_mut` would be a no-op."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " #![feature(cow_is_borrowed)]"] # [doc = " use std::borrow::Cow;"] # [doc = ""] # [doc = " let cow: Cow<'_, str> = Cow::Owned(\"moo\".to_string());"] # [doc = " assert!(cow.is_owned());"] # [doc = ""] # [doc = " let bull = Cow::Borrowed(\"...moo?\");"] # [doc = " assert!(!bull.is_owned());"] # [doc = " ```"] # [unstable (feature = "cow_is_borrowed" , issue = "65143")] pub const fn is_owned (& self) -> bool { ! self . is_borrowed () } # [doc = " Acquires a mutable reference to the owned form of the data."] # [doc = ""] # [doc = " Clones the data if it is not already owned."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " use std::borrow::Cow;"] # [doc = ""] # [doc = " let mut cow = Cow::Borrowed(\"foo\");"] # [doc = " cow.to_mut().make_ascii_uppercase();"] # [doc = ""] # [doc = " assert_eq!("] # [doc = "   cow,"] # [doc = "   Cow::Owned(String::from(\"FOO\")) as Cow<'_, str>"] # [doc = " );"] # [doc = " ```"] # [stable (feature = "rust1" , since = "1.0.0")] pub fn to_mut (& mut self) -> & mut < B as ToOwned > :: Owned { match * self { Borrowed (borrowed) => { * self = Owned (borrowed . to_owned ()) ; match * self { Borrowed (..) => unreachable ! () , Owned (ref mut owned) => owned , } } Owned (ref mut owned) => owned , } } # [doc = " Extracts the owned data."] # [doc = ""] # [doc = " Clones the data if it is not already owned."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " Calling `into_owned` on a `Cow::Borrowed` returns a clone of the borrowed data:"] # [doc = ""] # [doc = " ```"] # [doc = " use std::borrow::Cow;"] # [doc = ""] # [doc = " let s = \"Hello world!\";"] # [doc = " let cow = Cow::Borrowed(s);"] # [doc = ""] # [doc = " assert_eq!("] # [doc = "   cow.into_owned(),"] # [doc = "   String::from(s)"] # [doc = " );"] # [doc = " ```"] # [doc = ""] # [doc = " Calling `into_owned` on a `Cow::Owned` returns the owned data. The data is moved out of the"] # [doc = " `Cow` without being cloned."] # [doc = ""] # [doc = " ```"] # [doc = " use std::borrow::Cow;"] # [doc = ""] # [doc = " let s = \"Hello world!\";"] # [doc = " let cow: Cow<'_, str> = Cow::Owned(String::from(s));"] # [doc = ""] # [doc = " assert_eq!("] # [doc = "   cow.into_owned(),"] # [doc = "   String::from(s)"] # [doc = " );"] # [doc = " ```"] # [stable (feature = "rust1" , since = "1.0.0")] pub fn into_owned (self) -> < B as ToOwned > :: Owned { match self { Borrowed (borrowed) => borrowed . to_owned () , Owned (owned) => owned , } } }}}
